using System;using System.IO;using System.Text;using System.Collections;using OpenSim.Framework.Servers.HttpServer;
public static class Capture {public static string Trace="",Fail="";public static void Event(string s){Trace+=s+";";if(s==Fail)throw new Exception("injected");}public static string Hex(string s)=>s==null?"N":Convert.ToHexString(Encoding.UTF8.GetBytes(s)).ToLowerInvariant();}
namespace log4net {public interface ILog{void Warn(string m,Exception e);}public class Logger:ILog{public void Warn(string m,Exception e)=>Capture.Event("warn");}public static class LogManager{public static ILog GetLogger(Type t)=>new Logger();}}
namespace OSHttpServer {public interface IHttpRequest{Stream Body{get;}}public class HttpResponse{public HttpResponse(IHttpRequest r){Capture.Event("factory");}}public class Body:MemoryStream{public override bool CanRead{get{Capture.Event("read");return true;}}protected override void Dispose(bool d){Capture.Event("dispose");}}public class Incoming:IHttpRequest{Stream b=new Body();public Stream Body{get{Capture.Event("body");return b;}}}}
namespace OpenSim.Framework.Servers.HttpServer {public class OSHttpRequest{}public class OSHttpResponse{public OSHttpResponse(OSHttpServer.HttpResponse r){}public int StatusCode{set=>Capture.Event("status:"+value);}public long ContentLength64{set=>Capture.Event("length:"+value);}public Encoding ContentEncoding{set=>Capture.Event("utf8");}public bool KeepAlive{set=>Capture.Event(value?"keep:1":"keep:0");}public int KeepAliveTimeout{set=>Capture.Event("timeout:"+value);}public string ProtocolVersion{set{}}public string StatusDescription{set{}}public int RawBufferStart{set=>Capture.Event("start:"+value);}public int RawBufferLen{set=>Capture.Event("count:"+value);}public byte[] RawBuffer{set=>Capture.Event("buffer:"+Convert.ToHexString(value).ToLowerInvariant());}public void AddHeader(string k,string v)=>Capture.Event("header:"+k+":"+Capture.Hex(v));public void Redirect(string v,System.Net.HttpStatusCode c)=>Capture.Event("redirect:"+Capture.Hex(v));public void Send()=>Capture.Event("send");}}
class Program {static string Decode(string s)=>Encoding.UTF8.GetString(Convert.FromHexString(s));static void Main(){string line;while((line=Console.ReadLine())!=null){var a=line.Split('|');Capture.Trace="";Capture.Fail=a[7];var args=new PollServiceEventArgs(null,null,null,null,null,null,OpenMetaverse.UUID.Zero,0);args.RequestsHandled=int.Parse(a[9]);var request=new PollServiceHttpRequest(args,new OSHttpServer.Incoming());var data=new Hashtable();if(a[1]!="N")data["content_type"]=Decode(a[1]);data["str_response_string"]=Decode(a[2]);data["int_response_code"]=int.Parse(a[6]);if(a[8]=="long")data["int_response_code"]=(long)200;if(a[0]=="binary"){data["bin_response_data"]=new byte[]{0,1,2,253,254,255};data["bin_start"]=int.Parse(a[3]);data["int_bytes"]=int.Parse(a[4]);}if(a[0]=="prefab")data["h"]=new OSHttpResponse(null);if(a[0]=="nullprefab")data["h"]=null;if(a[0]=="badprefab")data["h"]=4;data["str_redirect_location"]="/next";bool error=false;try{if(a[0]=="stop")request.DoHTTPstop();else request.DoHTTPGruntWork(a[0]=="null"?null:data);}catch{error=true;}Console.WriteLine(Capture.Trace+"error:"+(error?1:0)+";handled:"+args.RequestsHandled+";consumed:"+(a[0]=="binary"&&data["bin_response_data"]==null?1:0));}}}
